/**
 * Local API v1 protocol contract (PRD v0.2).
 *
 * Frozen before any browser code: view models, command envelope, stable
 * error codes, and SSE replay rules. The HTTP adapter and SPA are both
 * pure consumers of this contract.
 */

import type { CheckRunEvidence, RunState, TaskKind, TaskStage } from "../types.ts";

// ---------------------------------------------------------------------------
// View models (immutable snapshots generated by SymphonyCore projections)
// ---------------------------------------------------------------------------

export interface TaskViewModel {
	id: string;
	title: string;
	kind: TaskKind;
	stage: TaskStage;
	runState: RunState;
	revision: number;
	updatedAt: string;
	acceptanceTotal: number;
	checks: Array<{ name: string; status: CheckRunEvidence["status"] }>;
	hasReports: { plan: boolean; implementation: boolean; review: boolean };
	integration?: { revision: string; targetBranch: string; integratedAt: string };
}

export interface SnapshotViewModel {
	projectionVersion: number;
	repositoryId: string;
	repositoryPath: string;
	configHash: string;
	configValid: boolean;
	tasks: TaskViewModel[];
	lastEventSequence: number;
	serverStartedAt: string;
}

// ---------------------------------------------------------------------------
// Command envelope (V02-CMD-001)
// ---------------------------------------------------------------------------

export const COMMAND_TYPES = [
	"task.create",
	"task.continue",
	"task.pause",
	"task.resume",
	"task.retry",
	"task.cancel",
	"task.advance",
	"task.approve_plan",
	"task.reject_plan",
	"task.record_integration",
	"task.complete",
	"checks.run",
	"report.submit",
] as const;
export type CommandType = (typeof COMMAND_TYPES)[number];

export interface CommandEnvelope {
	commandId: string;
	type: CommandType;
	repositoryId: string;
	aggregateId?: string;
	/** Optimistic concurrency: rejected with revision_conflict when stale. */
	expectedRevision?: number;
	payload: Record<string, unknown>;
}

export interface CommandAck {
	accepted: true;
	commandId: string;
	aggregateId?: string;
	resultingRevision?: number;
	next?: string;
}

export type CommandRejection =
	| { accepted: false; code: "unauthorized" }
	| { accepted: false; code: "bad_request"; detail: string }
	| { accepted: false; code: "unknown_command" }
	| { accepted: false; code: "unknown_repository" }
	| { accepted: false; code: "unknown_aggregate" }
	| { accepted: false; code: "revision_conflict"; currentRevision: number }
	| { accepted: false; code: "policy_violation"; reason: string }
	| { accepted: false; code: "config_invalid"; issues: Array<{ path: string; message: string }> }
	| { accepted: false; code: "internal_error"; detail: string };

// ---------------------------------------------------------------------------
// SSE event mapping (V02-SYNC-003)
// ---------------------------------------------------------------------------

export interface SseEvent {
	/** SymphonyEvent.eventId — usable as Last-Event-ID. */
	id: string;
	event: string;
	data: string;
}

export type SyncControlEvent =
	| { event: "hello"; data: { lastEventSequence: number } }
	| { event: "snapshot_required"; data: Record<string, never> };

export const SNAPSHOT_REQUIRED = "snapshot_required";

/**
 * Replay policy: retained window is bounded. If Last-Event-ID is older than
 * the window, the client must take a fresh snapshot instead.
 */
export function replayWindow<T extends { sequence: number }>(events: T[], lastEventIdSequence: number, windowSize: number):
	| { kind: "replay"; events: T[] }
	| { kind: "snapshot_required" } {
	if (events.length === 0) return { kind: "replay", events: [] };
	const oldest = events[0]!.sequence;
	if (lastEventIdSequence < oldest - 1) return { kind: "snapshot_required" };
	return { kind: "replay", events: events.filter((e) => e.sequence > lastEventIdSequence) };
}

// ---------------------------------------------------------------------------
// Validation
// ---------------------------------------------------------------------------

export function validateCommandEnvelope(raw: unknown): { ok: true; envelope: CommandEnvelope } | { ok: false; rejection: CommandRejection } {
	if (typeof raw !== "object" || raw === null) {
		return { ok: false, rejection: { accepted: false, code: "bad_request", detail: "body must be a JSON object" } };
	}
	const doc = raw as Record<string, unknown>;
	const { commandId, type, repositoryId, payload, aggregateId, expectedRevision } = doc;
	if (typeof commandId !== "string" || commandId.length < 8) {
		return { ok: false, rejection: { accepted: false, code: "bad_request", detail: "commandId is required" } };
	}
	if (typeof type !== "string" || !(COMMAND_TYPES as readonly string[]).includes(type)) {
		return { ok: false, rejection: { accepted: false, code: "unknown_command" } };
	}
	if (typeof repositoryId !== "string" || repositoryId.length === 0) {
		return { ok: false, rejection: { accepted: false, code: "bad_request", detail: "repositoryId is required" } };
	}
	if (payload !== undefined && (typeof payload !== "object" || payload === null || Array.isArray(payload))) {
		return { ok: false, rejection: { accepted: false, code: "bad_request", detail: "payload must be an object" } };
	}
	if (expectedRevision !== undefined && typeof expectedRevision !== "number") {
		return { ok: false, rejection: { accepted: false, code: "bad_request", detail: "expectedRevision must be a number" } };
	}
	return {
		ok: true,
		envelope: {
			commandId,
			type: type as CommandType,
			repositoryId,
			aggregateId: typeof aggregateId === "string" ? aggregateId : undefined,
			expectedRevision: typeof expectedRevision === "number" ? expectedRevision : undefined,
			payload: (payload ?? {}) as Record<string, unknown>,
		},
	};
}

/** Loopback binding validation — v0.2 rejects any non-loopback host (V02-WEB-001). */
export function assertLoopbackHost(host: string): { ok: true } | { ok: false; reason: string } {
	const allowed = new Set(["127.0.0.1", "localhost", "::1", "[::1]"]);
	if (!allowed.has(host)) {
		return { ok: false, reason: `v0.2 binds loopback only (got "${host}")` };
	}
	return { ok: true };
}

/** Origin/host checks for mutating routes (V02-AUTH-001). */
export function validateMutatingRequest(headers: {
	host?: string;
	origin?: string;
	authorization?: string;
	contentType?: string;
}, options: { expectedHost: string; expectedOrigin: string; token: string }): { ok: true } | { ok: false; status: number; reason: string } {
	const host = headers.host;
	if (!host || host !== options.expectedHost) {
		return { ok: false, status: 403, reason: "host header mismatch" };
	}
	if (headers.origin !== undefined) {
		// Full-origin comparison: scheme must match the local origin too.
		if (headers.origin !== options.expectedOrigin) {
			return { ok: false, status: 403, reason: "cross-origin mutation rejected" };
		}
	}
	if (!headers.authorization || headers.authorization !== `Bearer ${options.token}`) {
		return { ok: false, status: 401, reason: "missing or invalid session credential" };
	}
	if (headers.contentType !== "application/json") {
		return { ok: false, status: 415, reason: "content-type must be application/json" };
	}
	return { ok: true };
}

export const MAX_COMMAND_BODY_BYTES = 256 * 1024;
export const MAX_ARTIFACT_BYTES = 2 * 1024 * 1024;
export const MAX_SSE_RETAINED_EVENTS = 5_000;
